using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;

namespace JoinAssist
{
    internal sealed class HelpTopic
    {
        internal string Id, Category, Title, Summary, Example, Notes, Action, ActionLabel;
        internal string[] Steps, Related;
        public override string ToString()
        {
            return Category + " · " + Title;
        }
    }

    // Shipped inside the assembly: opening or searching the guide never needs a server.
    internal static class HelpContent
    {
        static HelpTopic Topic(string id, string category, string title, string summary, string[] steps, string example, string notes, string action, string actionLabel, params string[] related)
        {
            return new HelpTopic
            {
                Id = id,
                Category = category,
                Title = title,
                Summary = summary,
                Steps = steps,
                Example = example,
                Notes = notes,
                Action = action,
                ActionLabel = actionLabel,
                Related = related
            };
        }

        internal static readonly HelpTopic[] Topics =
        {
            Topic("start", "Inizia qui", "Primi passi e comandi", "JoinAssist prepara SQL nell'editor di SSMS 22 x64. Non esegue le query generate.", new[] { "Connetti una scheda query al database desiderato. Controlla il database selezionato nella barra di SSMS.", "Lascia attivo JoinAssist → Completamento automatico. Inizia un nome: la lista compare dopo l'attesa configurata.", "Usa ↑ / ↓ per scegliere e Tab per inserire; Invio funziona se abilitato. Un clic seleziona, il doppio clic inserisce. Esc chiude.", "Per richiamare la lista usa JoinAssist → Mostra suggerimenti: nel menu è indicata la tua scorciatoia attuale (inizialmente Ctrl+Alt+Spazio).", "Le funzioni che preparano script o elenchi si trovano in JoinAssist → Azioni rapide…; le preferenze in Impostazioni…. Guida… funziona anche senza query o connessione." }, "SELECT * FROM Ord\n-- Scegli Orders nella lista e premi Tab.", "Gli esempi della guida usano nomi fittizi: adattali al tuo database. Copia esempio modifica solo gli appunti, non la query. Ctrl+Z annulla l'inserimento nell'editor. I metadati visibili dipendono dai permessi dell'account.", null, null, "completion", "joins", "workspace", "troubleshooting"),
            Topic("completion", "Scrittura", "Tabelle, colonne e ricerca tollerante", "Completa nomi nel contesto della query, incluse colonne nei filtri DELETE / UPDATE e negli elenchi INSERT.", new[] { "Dopo FROM inizia il nome della tabella o vista e premi Tab sulla proposta corretta.", "Nelle espressioni inizia una colonna oppure scrivi alias. / tabella. per limitare le proposte a una sorgente. Se FROM dichiara un alias, usa quell'alias.", "Se mancano le proposte, usa Mostra suggerimenti; controlla sorgenti e database prima di aggiornare i metadati.", "In Impostazioni → Ricerca scegli Precisa, Equilibrata o Tollerante. La memoria delle scelte, facoltativa, ordina alternative di qualità simile per server/database." }, "SELECT o.Cust\nFROM Orders o\nWHERE o.Cust\n\nDELETE FROM Orders WHERE Cust", "I nomi esatti e i prefissi corretti precedono le correzioni. Schema e qualificatori restano letterali. I risultati rispettano gli ambiti: un alias di una sottoquery non è visibile fuori. Nessuna correzione viene applicata senza accettare una proposta.", "settings:Ricerca", "Apri impostazioni di ricerca", "sources", "typing", "troubleshooting"),
            Topic("sources", "Scrittura", "CTE, viste, APPLY e tabelle locali", "JoinAssist riconosce le sorgenti SQL risolvibili senza eseguire lo script.", new[] { "Definisci le CTE e gli alias nel testo della stessa query. Puoi completare colonne anche nel SELECT prima del FROM.", "Dichiara #temp o @tabella prima del punto di utilizzo nello stesso script; sono riconosciute CREATE TABLE, DECLARE TABLE e alcune SELECT INTO.", "OPENJSON propone key/value/type, oppure le colonne del WITH esplicito. Le altre sorgenti del FROM mantengono i propri suggerimenti." }, ";WITH RecentOrders AS (\n    SELECT Id, CustomerId FROM Orders\n)\nSELECT r.\nFROM RecentOrders r;", "Espressioni, viste e CTE ereditano FK solo con provenienza diretta e non ambigua. Tipi o forme non riconoscibili restano sconosciuti. Le #temp presenti solo in altre schede non vengono lette dalla sessione; @tabella termina a GO. Dynamic SQL, flussi condizionali e script incompleti possono impedire il riconoscimento.", null, null, "completion", "joins", "troubleshooting"),
            Topic("joins", "Scrittura", "JOIN, ON e foreign key comuni", "Propone le condizioni usando i vincoli reali, incluse chiavi composte e relazioni percorribili in entrambe le direzioni.", new[] { "Scrivi FROM con la prima tabella, poi INNER JOIN o LEFT JOIN seguito da uno spazio. Filtra il nome e accetta con Tab.", "Se la tabella è già scritta, scrivi ON e uno spazio: scegli la condizione FK. È supportato anche un ON semplice già iniziato.", "Per scegliere manualmente usa JoinAssist → JOIN da foreign key…. Controlla la condizione completa nell'anteprima.", "L'opzione in Impostazioni → Completamento abilita proposte «2 JOIN» e «1 JOIN · FK comuni». Il formato di schema, parentesi e alias si configura in Formato SQL." }, "SELECT * FROM Orders o\nINNER JOIN Customers c ON o.CustomerId = c.Id", "«FK comuni» collega due sorgenti che puntano alla stessa chiave completa di un padre: è una relazione ricavata, non una FK diretta, e può moltiplicare le righe o dare risultati diversi dai due JOIN. I vincoli non verificati sono segnalati. Colonne con nomi simili da sole non creano relazioni. ON non riscrive condizioni AND/OR già articolate. Per esplorare fino a cinque passaggi usa Azioni rapide.", "settings:Completamento", "Apri impostazioni di completamento", "paths", "format", "sources"),
            Topic("typing", "Scrittura", "Parole chiave, LIKE e IN con Tab", "Due opzioni indipendenti controllano le parole chiave e i modelli di filtro in Impostazioni → Completamento.", new[] { "Con Completa le parole chiave SQL attivo, scrivi sel e accetta SELECT con Tab.", "Dopo una colonna testuale, scrivi li / lik / LIKE e scegli la proposta LIKE '%%'. Tab prepara il filtro e mette il cursore fra i due %; vale anche per NOT LIKE.", "IN / NOT IN preparano ('', '') sul testo oppure ( ,) sugli altri tipi scalari supportati. Il cursore va nel primo valore.", "Per un elenco già copiato da Excel o dai risultati usa invece Azioni rapide → Elenco IN dagli appunti." }, "SELECT * FROM Customers WHERE Name LIKE '%%'\nSELECT * FROM Customers WHERE Name NOT IN ('', '')\nSELECT * FROM Orders WHERE Id IN ( ,)", "La colonna deve avere un tipo noto e non ambiguo. LIKE non aggiunge un modello a colonne non testuali. Valori già scritti restano invariati. Se la lista non è ancora comparsa, Tab può essere gestito normalmente dall'editor: attendi la proposta o richiama Mostra suggerimenti.", "settings:Completamento", "Apri opzioni parole chiave e filtri", "clipboard", "completion"),
            Topic("insert", "Scrittura", "Prepara INSERT e colonne mancanti", "Prepara colonne e VALUES senza leggere valori dal database.", new[] { "Scrivi INSERT INTO NomeTabella e uno spazio finale, poi scegli Prepara INSERT e premi Tab.", "Sostituisci o dichiara i parametri @nomeColonna generati. Il cursore parte dal primo valore.", "Dentro una posizione vuota della lista di colonne fra parentesi scegli Inserisci colonne mancanti; iniziando un nome restano le proposte singole.", "In Impostazioni → Completamento puoi escludere dalla struttura le colonne con un valore predefinito." }, "INSERT INTO Customers (Name, City)\nVALUES (@Name, @City);", "Le strutture multiple escludono identity, colonne calcolate, rowversion e generated always. Sono richieste proprietà note della tabella; viste, CTE e sinonimi non ricevono il modello completo. INSERT SELECT / VALUES / OUTPUT già iniziati non vengono sostituiti.", "settings:Completamento", "Apri opzioni INSERT", "completion", "columns"),
            Topic("star", "Scrittura", "Espandi SELECT *", "Sostituisce l'asterisco con le colonne esplicite scelte dall'utente.", new[] { "Posiziona il cursore sull'asterisco di SELECT * oppure alias.*.", "Apri JoinAssist → Espandi colonne (*)…, seleziona le colonne e controlla l'anteprima.", "Inserisci l'elenco. Vengono mantenuti gli alias esistenti e l'ordine delle sorgenti; Ctrl+Z annulla." }, "SELECT o.* FROM Orders o\n-- Può diventare: SELECT o.Id, o.CustomerId, o.CreatedAt FROM Orders o", "Non si applica a COUNT(*). Tutte le sorgenti di un * non qualificato devono essere risolvibili e senza output ambiguo; usa alias.* per limitarti a una sorgente. Se cambi query, cursore o connessione, riapri il comando.", null, null, "columns", "schema"),
            Topic("format", "Impostazioni", "Schema, parentesi, alias e formato SQL", "Le preferenze valgono per i nuovi frammenti generati, senza riformattare le query già scritte.", new[] { "Apri Impostazioni → Formato SQL.", "Scegli se inserire sempre schema, parentesi quadre e alias per le nuove tabelle JOIN.", "Scegli maiuscolo o minuscolo per le parole chiave generate e premi Salva." }, "INNER JOIN Customers ON Orders.CustomerId = Customers.Id\n-- Alias già presenti nella query vengono rispettati.", "Schema, parentesi o alias necessari per evitare ambiguità vengono comunque mantenuti. SQL letterale di scorciatoie, modelli e preferiti conserva il proprio stile. Le impostazioni riguardano tutte le schede e restano al prossimo avvio.", "settings:Formato SQL", "Apri formato SQL", "joins", "rules"),
            Topic("rules", "Personalizzazione", "Regole SELECT per tabella", "Aggiunge TOP e ordinamento a SELECT * semplici per una tabella o vista configurata.", new[] { "Apri Impostazioni → Regole → Nuova SELECT. Indica nome, schema e tabella; server/database vuoti significano tutti.", "Imposta TOP e ordinamento (prima colonna o colonna specifica); scegli DESC se necessario. Puoi caricare le colonne dalla query collegata.", "Premi Usa regola e poi Salva nelle impostazioni: fino a Salva le modifiche sono solo una bozza.", "Scrivi la SELECT corrispondente e accetta la proposta personale con Tab. L'opzione Applica anche con Spazio richiede nome completo, automatico attivo e una sola regola applicabile.", "Usa Prova… per verificare una regola prima di attivarla; puoi duplicare, disabilitare, importare ed esportare le regole." }, "SELECT * FROM logs.logs_tb\n-- Regola con TOP 100 / prima colonna / DESC:\nSELECT TOP 100 * FROM logs.logs_tb ORDER BY 1 DESC", "TOP, ORDER BY, WHERE e commenti esistenti sono conservati. JOIN, CTE, UNION, DISTINCT e SELECT INTO sono esclusi. L'ambito più specifico ha precedenza, ma regole equivalenti restano alternative e impediscono l'applicazione con Spazio. Le importazioni arrivano disabilitate con Spazio spento; esportazioni e preferenze contengono SQL e ambiti in chiaro.", "settings:Regole", "Apri regole personali", "snippets", "probe", "favorites"),
            Topic("snippets", "Personalizzazione", "Scorciatoie SQL e campi collegati", "Espande una parola in SQL personale; i campi ripetuti possono aggiornarsi insieme mentre li compili.", new[] { "In Impostazioni → Regole scegli Nuova scorciatoia. Imposta parola, SQL e facoltativo ambito server/database.", "Usa $cursor$ per un singolo punto di inserimento; oppure attiva Abilita campi collegati e usa {{nome:valore}} e {{nome}}. Non mescolare i due sistemi.", "Premi Usa regola e Salva. Scrivi la parola all'inizio di un'istruzione, dopo ; o GO e accetta con Tab.", "Con i campi collegati, Tab passa al prossimo nome distinto, Shift+Tab torna indietro e Esc termina. Lo stesso nome ripetuto segue la modifica del campo attivo." }, "SELECT TOP {{limite:100}} * FROM Orders\nWHERE CustomerId = {{id:0}} OR ParentCustomerId = {{id}};", "L'opzione campi collegati parte spenta per conservare le regole con parentesi graffe letterali. Il primo valore di ogni nome è quello usato. I campi sono testo SQL libero: non quotano né validano ciò che digiti. Modifiche fuori dal campo attivo o perdita del focus terminano la modalità. Limiti: 20 nomi / 100 occorrenze, 8.192 caratteri per scorciatoia personale.", "settings:Regole", "Apri scorciatoie personali", "templates", "rules", "probe"),
            Topic("workspace", "Azioni rapide", "Anteprima, inserimento e finestra affiancabile", "Il menu Azioni rapide raccoglie generatori, esplorazione dello schema, regole e preferiti.", new[] { "Apri JoinAssist → Azioni rapide… da una scheda SQL. Cerca l'azione e seleziona la sorgente dove richiesto.", "Compila le opzioni e prepara l'anteprima. Inserisci anteprima sostituisce la selezione catturata o inserisce al cursore; la rinomina alias sostituisce lo script intero.", "Copia SQL copia solo l'anteprima. Nuova scheda (salva .sql…) salva un file nel percorso scelto e lo apre in SSMS: verifica la connessione della nuova scheda.", "Mantieni aperto lascia una finestra separata accanto all'editor. Dopo aver cambiato o inserito testo usa Aggiorna dalla query e rigenera l'anteprima.", "Ctrl+Alt+P è una scorciatoia facoltativa, inizialmente spenta, abilitabile in Impostazioni → Completamento." }, null, "Un'anteprima perde validità se cambiano testo, cursore, selezione, scheda o connessione. Nessun SQL preparato viene eseguito. Il pannello non è agganciato alla struttura di SSMS. Sorgenti sconosciute richiedono una scelta esplicita.", "workflow:", "Apri azioni rapide", "related", "clipboard", "columns", "favorites"),
            Topic("related", "Azioni rapide", "Record collegati tramite foreign key", "Prepara SELECT per cercare record collegati alla sorgente, anche attraverso più tabelle.", new[] { "In Azioni rapide scegli Record collegati e la tabella di partenza.", "Scegli destinazione/percorso, colonna filtro e valore. Un valore vuoto produce un parametro da compilare.", "Prepara una SELECT per il percorso scelto, oppure una raccolta di SELECT con la modalità multipla. Controlla l'anteprima e inseriscila o copiala." }, "-- Esempio di obiettivo: trovare le righe di OrderItems\n-- collegate a Orders.Id = 42, seguendo le FK dichiarate.", "Non legge record o conteggi: genera SELECT TOP 100 con EXISTS per evitare di moltiplicare le righe della destinazione. La raccolta include al massimo 30 percorsi; la stessa tabella può comparire più volte tramite relazioni diverse. Cicli e passaggi ripetuti sulla stessa tabella sono esclusi.", "workflow:Record collegati", "Apri record collegati", "paths", "workspace", "delete"),
            Topic("clipboard", "Azioni rapide", "Appunti → IN / NOT IN", "Trasforma una colonna di valori in un elenco SQL tipizzato, con escaping e deduplicazione facoltativa.", new[] { "Copia una sola colonna senza intestazione da Excel o dai risultati; in Azioni rapide scegli Elenco IN dagli appunti.", "Premi Leggi appunti o incolla nel campo: una riga per valore. Scegli tipo, IN / NOT IN e rimozione duplicati.", "Premi Prepara elenco, controlla i valori e inserisci il frammento dopo la colonna da filtrare." }, "-- Testo copiato: O'Brien (una riga), 001 (un'altra riga)\nIN (N'O''Brien', N'001')", "Scegli testo per conservare gli zeri iniziali. I tipi numerici rifiutano testo non valido e decimali con virgola. Righe vuote sono saltate; tabulazioni sono rifiutate come input a più colonne. Limite 1.000 righe / 128 KiB. La parola NULL rimane testo, non SQL NULL: per quello usa IS NULL separatamente.", "workflow:Elenco IN dagli appunti", "Apri elenco dagli appunti", "typing", "workspace"),
            Topic("columns", "Azioni rapide", "Scegli più colonne", "Prepara un elenco di colonne da inserire nel punto scelto, senza partire da un asterisco.", new[] { "Metti il cursore nel SELECT o seleziona l'elenco da sostituire. Apri Azioni rapide → Scegli più colonne.", "Cerca e seleziona le colonne delle sorgenti riconosciute, oppure scegli un oggetto del catalogo se non ci sono sorgenti risolte.", "Prepara e inserisci l'anteprima. Le selezioni nascoste da una ricerca restano selezionate e l'ordine delle sorgenti viene mantenuto." }, "o.Id, o.CreatedAt, c.Name", "Gli alias esistenti vengono rispettati. Questa azione inserisce un elenco, non una SELECT intera. Controlla virgole e punto del cursore. Per sostituire direttamente SELECT * usa Espandi colonne (*)….", "workflow:Scegli più colonne", "Apri selezione colonne", "star", "workspace"),
            Topic("templates", "Azioni rapide", "Modello con campi modificabili", "Prepara SQL con punti da compilare e nomi ripetuti collegati.", new[] { "Apri Azioni rapide → Modello con campi e scrivi il modello con {{nome:valore}} e {{nome}}.", "Premi Prepara modello e controlla l'anteprima, poi Inserisci anteprima.", "Compila il campo selezionato. Tab / Shift+Tab navigano fra nomi distinti; Esc chiude la modalità. Puoi salvare SQL riutilizzabile nei preferiti o creare una scorciatoia personale." }, "SELECT * FROM Orders\nWHERE CustomerId = {{cliente:0}}\n   OR ParentCustomerId = {{cliente}};", "Campi letterali, senza conversione automatica in stringhe o parametri sicuri. Il primo valore definisce tutte le occorrenze di quel nome. Limiti: 20 nomi, 100 occorrenze, 64 KiB. La navigazione vale nell'editor catturato, non nel file aperto con Nuova scheda. Una modifica fuori dal campo o perdita del focus la termina.", "workflow:Modello con campi", "Apri modello con campi", "snippets", "favorites"),
            Topic("dates", "Azioni rapide", "Filtri temporali locale / UTC", "Genera intervalli senza convertire la colonna filtrata, usando inizio incluso e fine esclusa.", new[] { "Apri Azioni rapide → Filtro temporale e scegli la sorgente e una colonna data/ora.", "Scegli oggi, ieri, ultimi sette giorni, mese corrente o intervallo esplicito; seleziona orologio locale del server o UTC secondo come sono salvate le date.", "Prepara il filtro e inseriscilo nel WHERE. Per intervalli espliciti compila i parametri generati; la fine dell'intervallo non è inclusa." }, "CreatedAt >= @Da AND CreatedAt < @A", "Locale indica l'orologio del server SQL, non quello del PC. UTC non converte automaticamente i valori della colonna o i fusi orari. Il plugin prepara il predicato e non certifica il formato temporale usato dai dati.", "workflow:Filtro temporale", "Apri filtro temporale", "checks", "workspace"),
            Topic("paths", "Azioni rapide", "Percorsi JOIN e cardinalità", "Esplora fino a cinque relazioni FK e spiega dove potrebbero moltiplicarsi le righe.", new[] { "Apri Azioni rapide → Percorso JOIN e cardinalità. Scegli partenza, destinazione e profondità.", "Seleziona un percorso e leggi le indicazioni 0..1 / 0..N e gli eventuali vincoli non verificati.", "Genera e controlla la SELECT completa con i JOIN del percorso, poi inseriscila come nuova bozza." }, "-- Un percorso può essere Orders → Customers → Addresses.\n-- Le note descrivono l'unicità ricavata dagli indici, non conteggi reali.", "È una SELECT autonoma, non un'aggiunta automatica al FROM esistente. Le note dipendono da FK e indici univoci visibili; 0..N segnala una possibilità, non righe osservate. Massimo cinque passaggi, 30 alternative e 10.000 archi esplorati. Cicli, self-reference e tabelle ripetute sono esclusi. Riduci la profondità se il grafo è molto ampio.", "workflow:Percorso JOIN e cardinalità", "Apri percorsi JOIN", "joins", "related", "schema"),
            Topic("dependencies", "Esplorazione", "Dove viene usata una tabella o vista?", "Cerca dipendenze registrate nel catalogo SQL Server senza eseguire gli oggetti trovati.", new[] { "Apri Azioni rapide → Dove viene usato? e scegli la sorgente.", "Avvia la ricerca e consulta gli oggetti restituiti. Usa nomi e schema per proseguire con gli strumenti SSMS." }, null, "Fino a 500 risultati da sys.sql_expression_dependencies. Dynamic SQL, riferimenti esterni/non risolti e oggetti nascosti dai permessi possono mancare. L'assenza di risultati non dimostra che l'oggetto non sia usato. I risultati sono informazioni, non script eseguibili.", "workflow:Dove viene usato?", "Apri ricerca dipendenze", "column-search", "schema"),
            Topic("column-search", "Esplorazione", "Cerca colonne nello schema", "Trova le tabelle o viste che espongono un nome di colonna, anche se non sono nel FROM corrente.", new[] { "Apri Azioni rapide → Cerca colonne nello schema.", "Scrivi un frammento del nome e avvia la ricerca. Leggi schema, oggetto e colonna nei risultati." }, "CustomerId\n-- Cerca gli oggetti che espongono questo nome o frammento.", "Ricerca sul catalogo del database della scheda, limitata a 500 risultati e agli oggetti visibili all'account. Non cerca nei valori delle righe e non deduce relazioni dai nomi.", "workflow:Cerca colonne nello schema", "Apri ricerca colonne", "schema", "dependencies"),
            Topic("checks", "Azioni rapide", "Duplicati, NULL, conteggi e record orfani", "Genera query di controllo da rivedere ed eseguire personalmente.", new[] { "Apri Azioni rapide → Query di controllo e scegli la tabella.", "Scegli il controllo: duplicati, NULL, conteggio per valore/giorno, oppure righe senza padre tramite una FK uscente.", "Seleziona le colonne o la FK, prepara la bozza e controlla filtri e raggruppamenti prima di inserirla." }, "SELECT CustomerId, COUNT_BIG(*) AS Conteggio\nFROM Orders\nGROUP BY CustomerId\nHAVING COUNT_BIG(*) > 1;", "Le query non vengono eseguite dal plugin; non si leggono conteggi preventivi. Alcuni tipi non raggruppabili vengono rifiutati. Il controllo orfani usa NOT EXISTS e tutte le colonne delle FK composte, escludendo chiavi con NULL secondo il normale comportamento dei vincoli SQL Server.", "workflow:Query di controllo", "Apri query di controllo", "dates", "related"),
            Topic("favorites", "Personalizzazione", "Preferiti per database", "Salva esplicitamente query riutilizzabili con nome, categoria, descrizione e ambito.", new[] { "Seleziona il testo da salvare nell'editor, oppure usa lo script corrente. Apri Azioni rapide → Preferiti per database.", "Compila nome, categoria e descrizione; scegli connessione corrente o ambito globale e salva.", "Cerca il preferito, preparalo in anteprima e inseriscilo quando serve. Puoi aggiornarlo o eliminarlo; ripristina ultima eliminazione vale finché resta aperto quel pannello.", "Per aggiornare l'elenco nella ricerca generale dopo nuove modifiche usa Aggiorna dalla query." }, null, "I preferiti sono salvati su questo PC in %LOCALAPPDATA%/JoinAssist/favorites.json: SQL e ambiti sono in chiaro. Non è una cronologia automatica. Evita di salvarvi credenziali o dati riservati. Limiti: 200 voci, 64 KiB per query, 512 KiB di SQL totale. Modifiche concorrenti richiedono di riaprire il pannello prima di salvare.", "workflow:Preferiti per database", "Apri preferiti", "templates", "rules", "privacy"),
            Topic("schema", "Esplorazione", "Informazioni oggetti e schema affiancabile", "Consulta colonne, tipi, proprietà e relazioni senza leggere le righe della tabella.", new[] { "Per il dettaglio nel contesto, metti il cursore su tabella, alias o colonna qualificata e scegli JoinAssist → Informazioni tabella / colonna….", "Consulta Colonne e Relazioni FK. Per nomi ambigui usa alias.colonna.", "Per uno strumento da lasciare accanto all'editor apri JoinAssist → Schema affiancabile…; scegli la sorgente e Mantieni aperto.", "Dopo modifiche allo schema usa Aggiorna metadati e aggiorna la sorgente nella finestra." }, "SELECT o.CustomerId FROM Orders o\n-- Cursore su o.CustomerId → Informazioni tabella / colonna…", "Tipi, NULL, PK/FK, identity e colonne calcolate sono mostrati quando visibili. Non è un visualizzatore di dati e non certifica che una vista sia modificabile. Lo schema affiancabile è una finestra separata, non un pannello agganciato di SSMS.", "workflow:Schema affiancabile", "Apri schema affiancabile", "paths", "column-search", "star"),
            Topic("rename", "Azioni rapide", "Rinomina un alias con anteprima", "Aggiorna un alias e i riferimenti risolvibili, preservando commenti, stringhe e alias interni che lo nascondono.", new[] { "Posiziona il cursore dentro il SELECT interessato di una query completa.", "Apri Azioni rapide → Rinomina alias, scegli l'alias e il nuovo nome semplice.", "Controlla l'anteprima dell'intero script: Inserisci anteprima sostituisce tutto il testo catturato, non solo la selezione. Ctrl+Z annulla." }, "SELECT o.Id FROM Orders o WHERE o.CustomerId = 42;\n-- Rinominando o in ord:\nSELECT ord.Id FROM Orders ord WHERE ord.CustomerId = 42;", "La query deve essere analizzabile. Target DML, dichiarazioni non supportate e collisioni di nome vengono rifiutati. I riferimenti correlati vengono seguiti solo quando risolvibili. Testo, cursore o connessione cambiati rendono l'anteprima obsoleta: aggiorna e riprepara.", "workflow:Rinomina alias", "Apri rinomina alias", "workspace", "sources"),
            Topic("probe", "Personalizzazione", "Prova una regola e risolvi i conflitti", "Spiega perché una regola si applica o perché non viene proposta, senza modificare la query o le preferenze attive.", new[] { "In Impostazioni → Regole seleziona la regola e premi Prova…; puoi provare anche una bozza prima di salvare.", "In alternativa apri Azioni rapide → Prova una regola. Inserisci una query di esempio e premi Prova.", "Controlla disattivazione, ambito server/database, tabella/colonna mancante, SQL non supportato, TOP/ordine già presente e alternative concorrenti." }, "SELECT * FROM logs.logs_tb", "Le prove di regole legate a oggetti richiedono metadati della connessione corrente; le scorciatoie globali possono essere spiegate offline. Prova non salva né abilita la regola: Usa regola e Salva restano passaggi separati.", "settings:Regole", "Apri regole e prova", "rules", "snippets", "troubleshooting"),
            Topic("delete", "Operazioni avanzate", "DELETE con dipendenze", "Prepara uno script di prova che elimina prima le righe figlie e poi quelle della tabella di partenza.", new[] { "Scrivi una DELETE semplice completa di WHERE e posiziona il cursore al suo interno.", "Apri JoinAssist → Prepara DELETE con dipendenze…. Controlla Dipendenze e ordine, messaggi e Script SQL.", "Inserisci script di prova sostituisce solo la DELETE corrente. Lo script fissa gli insiemi di righe e segue FK su più livelli, anche composte.", "Rivedi filtro e parametri prima di eseguire. Il finale predefinito è ROLLBACK; per rendere definitiva una cancellazione occorre modificare manualmente il punto indicato dopo la revisione." }, "DELETE FROM Orders WHERE Id = @OrderId;\n-- Metti qui il cursore e usa il comando dedicato.", "Il plugin non esegue DELETE e non conta i dati. Servono VIEW DEFINITION sul database e PK visibili. Cicli/self-reference, trigger DML attivi, policy di sicurezza, tabelle temporali/history/memory-optimized e forme DELETE complesse sono bloccati. Niente script parziale se il piano non è affidabile. Lo script richiede assenza di transazioni aperte/implicite e imposta ROWCOUNT 0; ROLLBACK non rende l'esecuzione priva di costi, lock o effetti esterni dei trigger.", null, null, "related", "troubleshooting"),
            Topic("troubleshooting", "Supporto", "Suggerimenti mancanti, cache e diagnosi", "Passaggi utili quando una proposta non compare o l'anteprima non può essere inserita.", new[] { "Controlla il database e la connessione della scheda SQL, il cursore fuori da commenti/stringhe e gli alias corretti. Dopo JOIN serve uno spazio.", "Richiama Mostra suggerimenti con la scorciatoia indicata nel menu. Per errori temporanei usa Riprova suggerimenti in Azioni rapide → Diagnostica e recupero o Riprova proposte in Diagnostica….", "Dopo DDL usa JoinAssist → Aggiorna metadati e richiama le proposte. La cache resta separata per connessione/database; durata configurabile da 1 a 15 minuti (inizialmente 2).", "Se una finestra segnala query o connessione cambiata, usa Aggiorna dalla query o riapri il comando: una vecchia anteprima non viene inserita.", "Apri Diagnostica… e copia il report. Per segnalare un bug aggiungi un esempio con nomi fittizi e | nel punto del cursore." }, "SELECT o.Cust|\nFROM Orders o;", "Copia diagnostica omette query e dettagli di connessione. JA-SCOPE indica sorgenti/alias non risolti; JA-COLUMNS colonne non disponibili; JA-FK assenza di FK visibili; JA-METADATA / JA-TIMEOUT connessione o attesa; JA-MATCH nessuna corrispondenza. Per Microsoft Entra la scheda deve essere collegata con l'account corretto; un nuovo login globale non garantisce che la scheda esistente sia ricollegata. SQL complesso o metadati non visibili possono restare irrisolti.", "diagnostics", "Apri diagnostica", "completion", "cache", "updates"),
            Topic("cache", "Impostazioni", "Attesa, scorciatoie e cache metadati", "Controlla come vengono aperti i suggerimenti, senza cambiare il funzionamento delle query.", new[] { "In Impostazioni → Completamento scegli automatico, accettazione con Invio e attesa fra 70 e 2.000 ms. Tab accetta sempre una proposta aperta.", "Scegli la scorciatoia di richiamo fra Ctrl+Alt+Spazio, Ctrl+Shift+J e Ctrl+Alt+J. Ctrl+Alt+P per Azioni rapide è indipendente e facoltativo.", "In Cache scegli la durata dei metadati da 1 a 15 minuti; dopo modifiche allo schema aggiorna esplicitamente.", "Salva applica le modifiche per tutte le schede. Annulla conserva i valori precedenti; Azzera memoria delle scelte agisce subito, anche se poi annulli." }, null, "La cache è in memoria, non un elenco di dati del database. Scegli una scorciatoia alternativa se un altro plugin intercetta quella attuale. Con automatico spento puoi continuare a richiamare manualmente le proposte.", "settings:Cache", "Apri impostazioni cache", "completion", "privacy", "troubleshooting"),
            Topic("updates", "Supporto", "Aggiornamenti alla chiusura di SSMS", "Scarica la release pubblicata su GitHub e verifica il pacchetto prima di offrirne l'installazione.", new[] { "Apri JoinAssist → Aggiornamenti… e controlla versione e note. GitHub viene contattato aprendo la finestra o richiedendo il controllo.", "Installa alla prossima chiusura scarica e verifica il VSIX, poi attende che tutte le istanze SSMS siano chiuse. Continua a lavorare e salva le query prima di chiudere normalmente.", "Quando si apre l'installer Microsoft, completa i suoi passaggi. Il plugin non chiude né riapre SSMS e non conferma l'installer.", "Annulla installazione in attesa ferma l'attesa prima dell'avvio dell'installer. In alternativa scarica il VSIX e aprilo dopo aver chiuso SSMS." }, null, "Il codice dell'estensione viene caricato al nuovo avvio: non è un aggiornamento a caldo. Attesa massima 24 ore; dopo riavvio PC, disconnessione o errore può essere necessario riprogrammarla. Nessun controllo GitHub periodico in background. SHA-256 viene verificato; nessuna query o credenziale viene inviata.", "updates", "Apri aggiornamenti", "privacy", "troubleshooting"),
            Topic("privacy", "Supporto", "Dati locali e comportamento della guida", "La guida è inclusa nel plugin e non legge query, appunti, account o database per essere consultata.", new[] { "Preferenze e regole sono in %LOCALAPPDATA%/JoinAssist/preferences.json; i preferiti in favorites.json.", "La memoria delle scelte, se attiva, salva identificativi hash, conteggi e date in choices.json, senza testo SQL o credenziali.", "Lettura degli appunti, salvataggio di preferiti, esportazione regole e salvataggio file SQL richiedono un'azione esplicita. Le ricerche degli strumenti leggono metadati, non righe applicative.", "Copia esempio nella guida copia solo l'esempio statico. I pulsanti Apri… portano a una finestra del plugin; non applicano regole né inseriscono SQL." }, null, "Preferiti, regole ed esportazioni contengono il SQL e gli ambiti che salvi in chiaro. Non esiste una cronologia automatica delle query. L'aggiornamento su richiesta contatta GitHub; la consultazione della guida resta locale e offline. Il plugin non esegue il SQL preparato.", null, null, "favorites", "rules", "updates")
        };
        internal static HelpTopic Find(string id)
        {
            return Topics.FirstOrDefault(t => t.Id == id) ?? Topics[0];
        }

        internal static List<HelpTopic> Search(string query)
        {
            var terms = (query ?? "").Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
            return Topics.Where(t => terms.All(word => CultureInfo.InvariantCulture.CompareInfo.IndexOf(t.Category + " " + t.Title + " " + t.Summary + " " + string.Join(" ", t.Steps) + " " + t.Example + " " + t.Notes, word, CompareOptions.IgnoreCase | CompareOptions.IgnoreNonSpace) >= 0)).ToList();
        }

        internal static string WorkflowTopic(string name)
        {
            if (name == "Prova una regola")
                return "probe";
            if (name == "Diagnostica e recupero")
                return "troubleshooting";
            return Topics.FirstOrDefault(t => t.Action == "workflow:" + name)?.Id ?? "workspace";
        }
    }
}
